def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n//i)
    return sorted(divs)

solutions = []
for n in range(1, 500):
    divs = get_divisors(n)
    if len(divs) >= 6:
        # 6th largest is index -6 in 0-indexed list
